import{_ as t,o as a,c as i,a3 as r}from"./chunks/framework.CVt6dz2a.js";const b=JSON.parse('{"title":"EP.22 浏览器里的另一个世界","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.22-webxr.md","filePath":"comics/EP.22-webxr.md","lastUpdated":1793881879000}'),o={name:"comics/EP.22-webxr.md"};function s(d,e,l,n,h,c){return a(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="ep-22-浏览器里的另一个世界" tabindex="-1">EP.22 浏览器里的另一个世界 <a class="header-anchor" href="#ep-22-浏览器里的另一个世界" aria-label="Permalink to &quot;EP.22 浏览器里的另一个世界&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/22-webxr/basics">22.1 基础入门：WebXR 会话与最小改造</a> 延伸阅读：<a href="./../guide/22-webxr/advanced">进阶篇</a> · <a href="./../guide/22-webxr/practice">实战篇</a> 动手演示：<a href="./../public/demos/webxr/vr-showroom.html">vr-showroom 展厅 VR 化</a> · <a href="./../public/demos/webxr/ar-place.html">ar-place AR 产品放置</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>老板一句&quot;展厅做个 VR 版&quot;，像素酱眼前一黑：学 Unity、买头显、写 C#，这不得半年？</td></tr><tr><td>② 揭秘</td><td>码叔敲开浏览器：WebXR 是浏览器原生的沉浸式会话——<code>renderer.xr.enabled</code> + <code>VRButton</code> + <code>setAnimationLoop</code>，三行改造就进头显。</td></tr><tr><td>③ 实证</td><td>同一份展厅代码：桌面 OrbitControls 照看；戴上头显，手柄射线选展品；手机 AR 里瞄准环一扫，椅子落进真实客厅。</td></tr><tr><td>④ 结案</td><td>坑点清单：rAF 让 VR 画面冻住、非 HTTPS 按钮不出现、hit-test 要找有纹理的亮平面。码叔总结：一份场景，多端呈现。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-webxr-不是新引擎-是浏览器的新窗口" tabindex="-1">① WebXR 不是新引擎，是浏览器的新窗口 <a class="header-anchor" href="#_1-webxr-不是新引擎-是浏览器的新窗口" aria-label="Permalink to &quot;① WebXR 不是新引擎，是浏览器的新窗口&quot;">​</a></h3><p>面对&quot;做个 VR&quot;的需求，直觉是去学 Unity/Unreal。其实 WebXR 让浏览器本身成为 XR 运行时：</p><table tabindex="0"><thead><tr><th>顾虑</th><th>真相</th></tr></thead><tbody><tr><td>要学新引擎？</td><td>还是 three.js，场景代码一行不删</td></tr><tr><td>要装运行时？</td><td>Chrome / Edge / Quest Browser 原生支持</td></tr><tr><td>要买头显才能开发？</td><td>WebXR API Emulator 扩展即可模拟</td></tr></tbody></table><h3 id="_2-最小改造三行-一条纪律" tabindex="-1">② 最小改造三行 + 一条纪律 <a class="header-anchor" href="#_2-最小改造三行-一条纪律" aria-label="Permalink to &quot;② 最小改造三行 + 一条纪律&quot;">​</a></h3><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">renderer.xr.enabled </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                 // 打开 XR 通道</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">document.body.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">appendChild</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(VRButton.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">createButton</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(renderer)) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 入口按钮</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">renderer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setAnimationLoop</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(loop)                            </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 纪律：循环必须走它</span></span></code></pre></div><p>会话期间相机位姿由头显覆写，要移动玩家就移动相机的父级（dolly）；默认参考系 <code>local-floor</code>，场景单位就是真实世界的米。</p><h3 id="_3-vr-手柄-空间版射线拾取-ar-靠-hit-test" tabindex="-1">③ VR 手柄 = 空间版射线拾取，AR 靠 hit-test <a class="header-anchor" href="#_3-vr-手柄-空间版射线拾取-ar-靠-hit-test" aria-label="Permalink to &quot;③ VR 手柄 = 空间版射线拾取，AR 靠 hit-test&quot;">​</a></h3><p>10.1 的 Raycaster 思路原样搬进三维空间：起点换成手柄位置、方向换成手柄 -Z；<code>select</code> 事件对应 click；激光线命中缩短给出反馈——拾取、高亮、<code>userData</code> 挂数据，全部复用。AR 侧的核心是 hit-test：从视线向真实环境投射，命中平面就驱动 reticle 瞄准环，点屏把商品放到环上。</p><h3 id="_4-回退是产品底线" tabindex="-1">④ 回退是产品底线 <a class="header-anchor" href="#_4-回退是产品底线" aria-label="Permalink to &quot;④ 回退是产品底线&quot;">​</a></h3><p>桌面/手机浏览器打开 → OrbitControls 预览一个功能不丢；进入会话 → 相机交还头显、AR 隐藏虚拟地板、dom-overlay 显示工具条；退出 → 全部还原。iOS 不走 WebXR，Quick Look（USDZ + <code>rel=&quot;ar&quot;</code>）是常用兜底双轨。</p><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：进 VR 后画面冻住/黑屏？</strong> 渲染循环还在用 <code>requestAnimationFrame</code>——沉浸式会话里帧调度归 XR 系统，必须换成 <code>renderer.setAnimationLoop</code>。</li><li><strong>Q：VR 按钮根本不出现？</strong> WebXR 只在安全上下文可用：HTTPS 或 localhost；<code>http://</code> 局域网 IP 会被判定为不安全。</li><li><strong>Q：AR 里一直找不到平面？</strong> 平面检测需要光线充足 + 平面有纹理 + 缓慢移动手机建图；纯色桌面是最难识别的场景。</li><li><strong>Q：XR 里拖不动相机了？</strong> 会话中相机由头显姿态覆写，OrbitControls 要在 <code>sessionstart</code> 里禁用，退出再启用。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>为什么 WebXR 应用里渲染循环必须用 <code>renderer.setAnimationLoop</code>，而不能用 <code>window.requestAnimationFrame</code>？</li><li>桌面鼠标拾取和 VR 手柄拾取，在射线构造上有哪些异同？</li><li>一个 AR 电商页要同时服务 Android 与 iOS 用户，技术路线怎么选？</li></ol><details><summary>答案</summary><ol><li>进入沉浸式会话后，帧调度权从 window 移交给 XR 系统（头显刷新率 72/90/120Hz），window 的 rAF 不再代表头显刷新。<code>renderer.setAnimationLoop</code> 会在会话中自动切换为 <code>session.requestAnimationFrame</code>、退出后切回 window rAF，桌面与 XR 一套代码通吃。</li><li>相同点：都用同一个 Raycaster 求交、同一套 <code>userData</code>/高亮逻辑。不同点：桌面以 pointer 的 NDC + 相机用 <code>setFromCamera</code> 构造射线；手柄则以 <code>controller.matrixWorld</code> 取位置做起点、手柄 -Z 方向经矩阵变换做方向；触发从 click 换成 <code>select</code> 事件。</li><li>Android 走 WebXR（immersive-ar + hit-test）；iOS Safari 不支持 WebXR，用系统级 Quick Look 兜底——准备 USDZ 资产、以 <code>rel=&quot;ar&quot;</code> 链接调起。商品数据层尽量共用，只分叉呈现层。</li></ol></details>`,20)])])}const u=t(o,[["render",s]]);export{b as __pageData,u as default};
